int create_graphics_surface(struct drm_device *dev, void *data, struct drm_file *file_priv) {
    struct drm_mode_create_dumb *args = data;
    struct drm_gem_object *obj;
    struct drm_plane *plane;
    int ret = 0;

    if (!dev || !args || !file_priv) {
        return -EINVAL;
    }

    if (args->width <= 0 || args->height <= 0 || args->bpp <= 0) {
        return -EINVAL;
    }

    obj = drm_gem_object_create(dev, args->width * args->height * (args->bpp / 8));
    if (IS_ERR(obj)) {
        return PTR_ERR(obj);
    }

    plane = kzalloc(sizeof(*plane), GFP_KERNEL);
    if (!plane) {
        ret = -ENOMEM;
        goto free_gem;
    }

    plane->fb = drm_framebuffer_create(dev, args->width, args->height, args->bpp, obj);
    if (IS_ERR(plane->fb)) {
        ret = PTR_ERR(plane->fb);
        goto free_plane;
    }

    ret = drm_mode_object_add(dev, &plane->base, DRM_MODE_OBJECT_PLANE);
    if (ret) {
        goto free_framebuffer;
    }

    args->handle = drm_gem_handle_create(file_priv, obj);
    if (!args->handle) {
        ret = -EINVAL;
        goto remove_plane;
    }

    return 0;

remove_plane:
    drm_mode_object_remove(dev, &plane->base);
free_framebuffer:
    drm_framebuffer_cleanup(plane->fb);
free_plane:
    kfree(plane);
free_gem:
    drm_gem_object_put(obj);
    return ret;
}
